mapper.select:


    c.dept_id is not null

        AND c.name like concat('%', #{name}, '%')


        AND c.provider = #{provider}


        AND (
            c.dept_id = #{deptId}
            OR c.dept_id in (
                select child.dept_id
                from sys_dept child
                where child.del_flag = '0'
                  and find_in_set(#{deptId}, child.ancestors)
            )
        )


        AND c.dept_id = #{deptId}


        AND c.is_active = #{isActive}

    ${params.dataScope}

order by c.dept_id, c.created_at desc


where c.dept_id is null
  and c.created_by = #{createdBy}
order by c.created_at desc

mapper.update:
update team_model_configs
name = #{name}, provider = #{provider}, base_url = #{baseUrl}, model = #{model}, api_key_hash = #{apiKeyHash}, dept_id = #{deptId}, recipient_id = #{recipientId}, is_active = #{isActive},
where id = #{id}

mapper.delete:
delete from team_model_configs
where id = #{id}
  and created_by = #{createdBy}
  and dept_id is null
